/// <summary>
///     AVA <c>displayAVAEmailInvoice</c> method.
///     AVA - Schneider 15.03.2024
/// </summary>
/// <returns>
///     <c>AVAEmailInvoice</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAEmailInvoice displayAVAEmailInvoice()
{
    AVAEmailInvoice   retVal;

    CustTable locCustTable;

    if(this.CustAccount)
    {
        locCustTable = CustTable::find(this.CustAccount);

        retVal = locCustTable.AVAEmailInvoice;
    }

    return retVal;
}

/// <summary>
///     AVA <c>avaKCS_TOSTable</c> method.
///     AVA - Schneider 15.03.2024
/// </summary>
/// <returns>
///     <c>KCS_TOSTable</c> as return value
/// </returns>
public KCS_TOSTable avaKCS_TOSTable()
{
    KCS_TOSTable retVal;

    retVal = KCS_TOSTable::find(this.TOSId);

    return retVal;
}
